import { SchemaScript } from "./schema-script";
import type { FaqItem } from "./types";

type FAQModuleProps = {
  title: string;
  intro?: string;
  items: FaqItem[];
  includeFaqSchema?: boolean;
};

export function FAQModule({
  title,
  intro,
  items,
  includeFaqSchema = false,
}: FAQModuleProps) {
  const faqSchema = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: items.map((item) => ({
      "@type": "Question",
      name: item.question,
      acceptedAnswer: {
        "@type": "Answer",
        text: item.answer,
      },
    })),
  };

  return (
    <section aria-labelledby="faq-heading" className="space-y-8">
      {includeFaqSchema ? <SchemaScript schema={faqSchema} /> : null}
      <header className="space-y-4">
        <h2 id="faq-heading" className="text-3xl leading-tight tracking-tight text-[#EAEAEA] md:text-5xl">
          {title}
        </h2>
        {intro ? <p className="max-w-4xl text-lg text-[#B0B0B0]">{intro}</p> : null}
      </header>

      <div className="border-t border-divider">
        {items.map((item) => (
          <details key={item.question} className="border-b border-divider py-5">
            <summary className="cursor-pointer list-none pr-6 text-lg leading-snug text-[#EAEAEA]">
              {item.question}
            </summary>
            <p className="pt-4 max-w-4xl text-base leading-relaxed text-[#B0B0B0] md:text-lg">
              {item.answer}
            </p>
          </details>
        ))}
      </div>
    </section>
  );
}
