import { buildArticleSchema, SchemaScript } from "./schema-script";

type AnswerBlockProps = {
  title: string;
  answer: string;
  detail?: string;
  detailLabel?: string;
  includeArticleSchema?: boolean;
};

export function AnswerBlock({
  title,
  answer,
  detail,
  detailLabel = "Se utdypning",
  includeArticleSchema = false,
}: AnswerBlockProps) {
  return (
    <article className="space-y-6">
      {includeArticleSchema ? (
        <SchemaScript
          schema={buildArticleSchema({
            headline: title,
            description: answer,
          })}
        />
      ) : null}
      <h2 className="text-3xl leading-tight tracking-tight text-[#EAEAEA] md:text-5xl">
        {title}
      </h2>
      <p className="max-w-4xl text-lg leading-relaxed text-[#EAEAEA] md:text-xl">
        {answer}
      </p>
      {detail ? (
        <details className="max-w-4xl border-t border-divider pt-5 text-[#B0B0B0]">
          <summary className="cursor-pointer list-none text-sm uppercase tracking-[0.14em] text-[#EAEAEA]/75">
            {detailLabel}
          </summary>
          <p className="pt-4 text-base leading-relaxed md:text-lg">{detail}</p>
        </details>
      ) : null}
    </article>
  );
}
